diff --git a/applets/kicker/combinationmodel.cpp b/applets/kicker/combinationmodel.cpp
new file mode 100644
index 0000000000..1272e20da3
--- /dev/null
+++ b/applets/kicker/combinationmodel.cpp
@@ -0,0 +1,178 @@
+/*
+ *    SPDX-FileCopyrightText: 2026 Christoph Wolk <cwo.kde@posteo.net>
+ *
+ *    SPDX-License-Identifier: GPL-2.0-or-later
+ */
+
+#include "combinationmodel.h"
+#include "abstractmodel.h"
+
+#include <QAbstractItemModel>
+#include <QConcatenateTablesProxyModel>
+#include <QTimer>
+
+bool DeduplicationProxyModel::filterAcceptsRow(int source_row, const QModelIndex &source_parent) const
+{
+    Q_UNUSED(source_parent);
+
+    const QModelIndex sourceIndex = sourceModel()->index(source_row, 0);
+    if (!sourceIndex.isValid()) {
+        return false;
+    }
+
+    const QVariant key = sourceIndex.data(m_keyRole);
+
+    for (QAbstractItemModel *model : m_models) {
+        if (model && !model->match(model->index(0, 0), m_keyRole, key, 1, Qt::MatchFlags(Qt::MatchFixedString | Qt::MatchCaseSensitive)).empty()) {
+            return false;
+        }
+    }
+    return true;
+}
+
+DeduplicationProxyModel::DeduplicationProxyModel(QObject *parent, QAbstractItemModel *sourceModel, int keyRole, QList<QAbstractItemModel *> comparisonModels)
+    : QSortFilterProxyModel(parent)
+    , m_keyRole(keyRole)
+    , m_models(comparisonModels)
+{
+    setSourceModel(sourceModel);
+    for (QAbstractItemModel *model : comparisonModels) {
+        if (sourceModel && model) {
+            connect(model, &QAbstractItemModel::dataChanged, this, &QSortFilterProxyModel::invalidate, Qt::QueuedConnection);
+            connect(model, &QAbstractItemModel::modelReset, this, &QSortFilterProxyModel::invalidate, Qt::QueuedConnection);
+            connect(model, &QAbstractItemModel::rowsInserted, this, &QSortFilterProxyModel::invalidate, Qt::QueuedConnection);
+            connect(model, &QAbstractItemModel::rowsRemoved, this, &QSortFilterProxyModel::invalidate, Qt::QueuedConnection);
+        }
+    }
+}
+
+DeduplicationProxyModel::~DeduplicationProxyModel() = default;
+
+ConcatenationModel::ConcatenationModel(QObject *parent, int keyRole, AbstractModel *firstModel, AbstractModel *secondModel, AbstractModel *thirdModel)
+    : QSortFilterProxyModel(parent)
+    , m_firstModel(firstModel)
+    , m_secondModel(secondModel)
+    , m_deduplicatedSecondModel(new DeduplicationProxyModel(this, secondModel, keyRole, {firstModel}))
+    , m_thirdModel(thirdModel)
+    , m_deduplicatedThirdModel(new DeduplicationProxyModel(this, thirdModel, keyRole, {firstModel, secondModel}))
+    , m_sourceModel(new QConcatenateTablesProxyModel(this))
+{
+    m_sourceModel->addSourceModel(firstModel);
+    connect(firstModel, &QAbstractItemModel::rowsRemoved, this, &QSortFilterProxyModel::invalidate, Qt::QueuedConnection);
+    connect(firstModel, &QAbstractItemModel::rowsInserted, this, &QSortFilterProxyModel::invalidate, Qt::QueuedConnection);
+    connect(firstModel, &QAbstractItemModel::dataChanged, this, &QSortFilterProxyModel::invalidate, Qt::QueuedConnection);
+    if (secondModel) {
+        m_sourceModel->addSourceModel(m_deduplicatedSecondModel);
+        connect(secondModel, &QAbstractItemModel::rowsInserted, this, &QSortFilterProxyModel::invalidate, Qt::QueuedConnection);
+        connect(secondModel, &QAbstractItemModel::rowsRemoved, this, &QSortFilterProxyModel::invalidate, Qt::QueuedConnection);
+        connect(secondModel, &QAbstractItemModel::dataChanged, this, &QSortFilterProxyModel::invalidate, Qt::QueuedConnection);
+    }
+    if (thirdModel) {
+        m_sourceModel->addSourceModel(m_deduplicatedThirdModel);
+        connect(thirdModel, &QAbstractItemModel::rowsInserted, this, &QSortFilterProxyModel::invalidate, Qt::QueuedConnection);
+        connect(thirdModel, &QAbstractItemModel::rowsRemoved, this, &QSortFilterProxyModel::invalidate, Qt::QueuedConnection);
+        connect(thirdModel, &QAbstractItemModel::dataChanged, this, &QSortFilterProxyModel::invalidate, Qt::QueuedConnection);
+    }
+
+    setSourceModel(m_sourceModel);
+}
+
+ConcatenationModel::~ConcatenationModel() = default;
+
+bool ConcatenationModel::filterAcceptsRow(int source_row, const QModelIndex &source_parent) const
+{
+    Q_UNUSED(source_parent);
+
+    // qDebug() << "first" << m_firstModel->rowCount();
+    // qDebug() << "second" << m_deduplicatedSecondModel->rowCount();
+    // qDebug() << "third" << m_deduplicatedThirdModel->rowCount();
+
+    if (source_row >= m_firstModel->rowCount() + m_deduplicatedSecondModel->rowCount() + m_deduplicatedThirdModel->rowCount()) {
+        return false;
+    }
+
+    const QModelIndex sourceIndex = m_sourceModel->mapToSource(m_sourceModel->index(source_row, 0));
+
+    bool inFirstModel = sourceIndex.model() == m_firstModel;
+    bool inSecondModel = sourceIndex.model() == m_deduplicatedSecondModel;
+    bool inThirdModel = sourceIndex.model() == m_deduplicatedThirdModel;
+
+    auto initialTargets = [this](QAbstractItemModel *model, int minItems) {
+        if (!model) {
+            return 0;
+        }
+        return (minItems == -1 || m_globalTargetItems == -1) ? model->rowCount() : minItems;
+    };
+
+    int itemsFromFirstModel = initialTargets(m_firstModel, m_firstMinItems);
+    int itemsFromSecondModel = initialTargets(m_deduplicatedSecondModel, m_secondMinItems);
+    int itemsFromThirdModel = initialTargets(m_deduplicatedThirdModel, m_thirdMinItems);
+
+    auto distribute = [](QAbstractItemModel *model, int &included, int &missing) {
+        if (missing <= 0 || !model) {
+            return;
+        }
+        int available = model->rowCount() - included;
+        int delta = std::min(available, missing);
+        included += delta;
+        missing -= delta;
+    };
+
+    int missing = m_globalTargetItems - itemsFromFirstModel - itemsFromSecondModel - itemsFromThirdModel;
+
+    distribute(m_firstModel, itemsFromFirstModel, missing);
+    distribute(m_deduplicatedSecondModel, itemsFromSecondModel, missing);
+    distribute(m_deduplicatedThirdModel, itemsFromThirdModel, missing);
+
+    return ((inFirstModel && sourceIndex.row() < itemsFromFirstModel) || (inSecondModel && sourceIndex.row() < itemsFromSecondModel)
+            || (inThirdModel && sourceIndex.row() < itemsFromThirdModel));
+}
+
+bool ConcatenationModel::trigger(int row, const QString &actionId, const QVariant &argument) const
+{
+    QModelIndex sourceIndex = m_sourceModel->mapToSource(mapToSource(index(row, 0)));
+    AbstractModel *model = sourceIndex.model() == m_firstModel ? m_firstModel
+        : sourceIndex.model() == m_deduplicatedSecondModel     ? m_secondModel
+        : sourceIndex.model() == m_deduplicatedThirdModel      ? m_thirdModel
+                                                               : nullptr;
+    if (!model) {
+        return false;
+    }
+    const DeduplicationProxyModel *proxyModel = qobject_cast<const DeduplicationProxyModel *>(sourceIndex.model());
+    if (proxyModel) {
+        sourceIndex = proxyModel->mapToSource(sourceIndex);
+    }
+    return model->trigger(sourceIndex.row(), actionId, argument);
+}
+
+void ConcatenationModel::setLimits(int globalTargetItems, int firstMinItems, int secondMinItems, int thirdMinItems)
+{
+    if (globalTargetItems == m_globalTargetItems && firstMinItems == m_firstMinItems && secondMinItems == m_secondMinItems
+        && thirdMinItems == m_thirdMinItems) {
+        return;
+    }
+    m_globalTargetItems = globalTargetItems;
+    m_firstMinItems = firstMinItems;
+    m_secondMinItems = secondMinItems;
+    m_thirdMinItems = thirdMinItems;
+    invalidate();
+}
+
+CombinationModel::CombinationModel(QObject *parent, int deduplicationKeyRole, AbstractModel *firstModel, AbstractModel *secondModel, AbstractModel *thirdModel)
+    : ForwardingModel(parent)
+    , m_concatenationModel(new ConcatenationModel(this, deduplicationKeyRole, firstModel, secondModel, thirdModel))
+{
+    setSourceModel(m_concatenationModel);
+}
+
+CombinationModel::~CombinationModel() = default;
+
+void CombinationModel::setLimits(int globalTargetItems, int firstMinItems, int secondMinItems, int thirdMinItems)
+{
+    m_concatenationModel->setLimits(globalTargetItems, firstMinItems, secondMinItems, thirdMinItems);
+}
+
+bool CombinationModel::trigger(int row, const QString &actionId, const QVariant &argument)
+{
+    return m_concatenationModel->trigger(row, actionId, argument);
+}
