new file mode 100644
index 0000000000..33b32544eb
--- /dev/null
+++ b/applets/kicker/combinationmodel.h
@@ -0,0 +1,90 @@
+/*
+ *    SPDX-FileCopyrightText: 2026 Christoph Wolk <cwo.kde@posteo.net>
+ *
+ *    SPDX-License-Identifier: GPL-2.0-or-later
+ */
+
+#pragma once
+
+#include "forwardingmodel.h"
+#include <QSortFilterProxyModel>
+
+class AbstractModel;
+class QConcatenateTablesProxyModel;
+
+class DeduplicationProxyModel : public QSortFilterProxyModel
+{
+    Q_OBJECT
+
+public:
+    explicit DeduplicationProxyModel(QObject *parent, QAbstractItemModel *sourceModel, int keyRole, QList<QAbstractItemModel *> comparisonModels);
+    ~DeduplicationProxyModel() override;
+
+protected:
+    bool filterAcceptsRow(int source_row, const QModelIndex &source_parent) const override;
+
+    int m_keyRole;
+    QList<QAbstractItemModel *> m_models;
+};
+
+class ConcatenationModel : public QSortFilterProxyModel
+{
+    Q_OBJECT
+
+public:
+    explicit ConcatenationModel(QObject *parent,
+                                int keyRole,
+                                AbstractModel *firstModel,
+                                AbstractModel *secondModel = nullptr,
+                                AbstractModel *thirdModel = nullptr);
+    ~ConcatenationModel() override;
+
+    // Model always contains minItems from the respective model (if there are enough), then fills
+    // up to globalTargetItems if that is higher than the sum of minItems. -1 for unlimited.
+    // Note that entries are deduplicated before we check what to include; so if the first models
+    // are not unlimited, a higher-ranked entry in the later models may not show up if it's also
+    // low ranked in an earlier model.
+    void setLimits(int globalTargetItems = -1, int firstMinItems = -1, int secondMinItems = -1, int thirdMinItems = -1);
+
+public Q_SLOTS:
+    bool trigger(int row, const QString &actionId, const QVariant &argument) const;
+
+protected:
+    bool filterAcceptsRow(int source_row, const QModelIndex &source_parent) const override;
+
+    int m_firstMinItems = -1;
+    int m_secondMinItems = -1;
+    int m_thirdMinItems = -1;
+    int m_globalTargetItems = -1;
+
+    AbstractModel *m_firstModel;
+    AbstractModel *m_secondModel;
+    DeduplicationProxyModel *m_deduplicatedSecondModel;
+    AbstractModel *m_thirdModel;
+    DeduplicationProxyModel *m_deduplicatedThirdModel;
+    QConcatenateTablesProxyModel *m_sourceModel;
+};
+
+class CombinationModel : public ForwardingModel
+{
+    Q_OBJECT
+
+public:
+    explicit CombinationModel(QObject *parent,
+                              int deduplicationKeyRole,
+                              AbstractModel *firstModel = nullptr,
+                              AbstractModel *secondModel = nullptr,
+                              AbstractModel *thirdModel = nullptr);
+    ~CombinationModel() override;
+
+    void setLimits(int globalTargetItems = -1, int firstMinItems = -1, int secondMinItems = -1, int thirdMinItems = -1);
+
+    Q_INVOKABLE bool trigger(int row, const QString &actionId, const QVariant &argument) override;
+
+Q_SIGNALS:
+
+private Q_SLOTS:
+
+private:
+    ConcatenationModel *m_concatenationModel = nullptr;
+};
