+MimeTypeFilterModel::MimeTypeFilterModel(QObject *parent, MimetypeCategory mimeTypeCategory, int mimeTypeRole)
+    : QSortFilterProxyModel(parent)
+    , m_mimeTypeCategory(mimeTypeCategory)
+    , m_mimeTypeRole(mimeTypeRole)
+{
+}
+
+MimeTypeFilterModel::~MimeTypeFilterModel() = default;
+
+bool MimeTypeFilterModel::filterAcceptsRow(int source_row, const QModelIndex &source_parent) const
+{
+    Q_UNUSED(source_parent)
+    QString mimeType = sourceModel()->index(source_row, 0).data(m_mimeTypeRole).toString();
+    switch (m_mimeTypeCategory) {
+    case MimetypeCategory::Applications:
+        return mimeType.isEmpty();
+    case MimetypeCategory::Folders:
+        return mimeType == QStringLiteral("inode/directory");
+    case MimetypeCategory::Files:
+        return !mimeType.isEmpty() && mimeType != QStringLiteral("inode/directory");
+    default:
+        return true;
+    }
+}
+
+NewlyInstalledFilterProxy::NewlyInstalledFilterProxy(QObject *parent)
+    : QSortFilterProxyModel(parent)
+{
+}
+
+NewlyInstalledFilterProxy::~NewlyInstalledFilterProxy() = default;
+
+bool NewlyInstalledFilterProxy::filterAcceptsRow(int source_row, const QModelIndex &source_parent) const
+{
+    Q_UNUSED(source_parent);
+
+    return sourceModel()->index(source_row, 0).data(Kicker::IsNewlyInstalledRole).toBool();
+}
+
+DashModel::DashModel(QObject *parent,
+                     AbstractModel *favoritesModel,
+                     AbstractModel *newlyInstalledModel,
+                     AbstractModel *recentAppsModel,
+                     AbstractModel *recentFilesModel,
+                     AbstractModel *recentFolderModel)
+    : QAbstractListModel(parent)
+{
+    FilterModel *favoriteAppsModel =
+        new FilterModel(this, favoritesModel, new MimeTypeFilterModel(this, MimeTypeFilterModel::Applications, Kicker::MimeTypeRole));
+
+    FilterModel *newAppsModel = nullptr;
+    if (newlyInstalledModel) {
+        newAppsModel = new FilterModel(this, newlyInstalledModel, new NewlyInstalledFilterProxy(this));
+    }
+
+    m_appModel = new CombinationModel(this, Kicker::FavoriteIdRole, favoriteAppsModel, newAppsModel, recentAppsModel);
+    m_appModel->setLimits(12, -1, -1, 5);
+    m_appModel->setFavoritesModel(favoritesModel);
+
+    FilterModel *favoriteFilesModel = new FilterModel(this, favoritesModel, new MimeTypeFilterModel(this, MimeTypeFilterModel::Files, Kicker::MimeTypeRole));
+
+    m_fileModel = new CombinationModel(this, Kicker::FavoriteIdRole, favoriteFilesModel, recentFilesModel);
+
+    m_fileModel->setLimits(7, -1, 5, 0);
+    m_fileModel->setFavoritesModel(favoritesModel);
+
+    FilterModel *favoriteFolderModel = new FilterModel(this, favoritesModel, new MimeTypeFilterModel(this, MimeTypeFilterModel::Folders, Kicker::MimeTypeRole));
+
+    m_folderModel = new CombinationModel(this, Kicker::FavoriteIdRole, favoriteFolderModel, recentFolderModel);
+    m_folderModel->setLimits(7, -1, 5, 0);
+    m_folderModel->setFavoritesModel(favoritesModel);
+}
+
+DashModel::~DashModel()
+{
+    delete m_appModel;
+    m_appModel = nullptr;
+}
+
+QVariant DashModel::data(const QModelIndex &index, int role) const
+{
+    if (!index.isValid() || index.row() >= count()) {
+        return {};
+    }
+
+    if (role == Qt::DisplayRole) {
+        switch (index.row()) {
+        case 0:
+            return i18n("Applications");
+        case 1:
+            return i18n("Files");
+        case 2:
+            return i18n("Folders");
+        default:
+            return QString();
+        }
+    }
+
+    return {};
+}
+
+QHash<int, QByteArray> DashModel::roleNames() const
+{
+    return {{Qt::DisplayRole, QByteArrayLiteral("description")}};
+}
+
+int DashModel::rowCount(const QModelIndex &parent) const
+{
+    return parent.isValid() ? 0 : ((m_appModel != nullptr) + (m_fileModel != nullptr) + (m_folderModel != nullptr));
+}
+
+int DashModel::count() const
+{
+    return rowCount();
+}
+
+AbstractModel *DashModel::appModel() const
+{
+    return m_appModel;
+}
+
+AbstractModel *DashModel::fileModel() const
+{
+    return m_fileModel;
+}
+
+AbstractModel *DashModel::folderModel() const
+{
+    return m_folderModel;
+}
+
+AbstractModel *DashModel::modelForRow(int row) const
+{
+    switch (row) {
+    case 0:
+        return m_appModel;
+    case 1:
+        return m_fileModel;
+    case 2:
+        return m_folderModel;
+    default:
+        return nullptr;
+    }
+    return m_folderModel;
+}
