+#include <QConcatenateTablesProxyModel>
+#include <QSortFilterProxyModel>
+
+FilterModel::FilterModel(QObject *parent, AbstractModel *dataModel, QSortFilterProxyModel *proxyModel)
+    : ForwardingModel(parent)
+    , m_proxyModel(proxyModel)
+    , m_dataModel(dataModel)
+{
+    setSourceModel(proxyModel);
+    if (proxyModel) {
+        proxyModel->setSourceModel(dataModel);
+    }
+}
+
+FilterModel::~FilterModel() = default;
+
+Q_INVOKABLE bool FilterModel::trigger(int row, const QString &actionId, const QVariant &argument)
+{
+    if (m_dataModel) {
+        QModelIndex sourceIndex = m_proxyModel->index(row, 0, {});
+        QModelIndex dataIndex = m_proxyModel->mapToSource(sourceIndex);
+        return m_dataModel->trigger(dataIndex.row(), actionId, argument);
+    }
+    return false;
+}
